use mockall::predicate::eq;

#[automock]
trait Warehouse { fn remove(&mut self, sku: &str, qty: u32) -> bool; }

let mut mock = MockWarehouse::new();
mock.expect_remove().with(eq("Talisker"), eq(50)).times(1).returning(|_, _| true);

assert!(fill(&mut mock, "Talisker", 50));
mock.checkpoint();
